import {
    BooleanColumn,
    ChoiceColumn,
    DateTimeColumn,
    GenericColumn,
    IntegerColumn,
    ReferenceColumn,
    Table,
} from '../../db'

export const sc_req_item = Table({
    name: 'sc_req_item',
    extends: 'task',
    schema: {
        backordered: BooleanColumn({ mandatory: false, label: 'Backordered', read_only: false, active: true }),
        billable: BooleanColumn({ mandatory: false, label: 'Billable', read_only: false, active: true }),
        cat_item: ReferenceColumn({
            mandatory: false,
            label: 'Item',
            read_only: false,
            active: true,
            referenceTable: 'sc_cat_item',
        }),
        configuration_item: ReferenceColumn({
            mandatory: false,
            label: 'Configuration item',
            read_only: false,
            active: true,
            referenceTable: 'cmdb_ci',
        }),
        context: ReferenceColumn({
            mandatory: false,
            label: 'Context',
            read_only: false,
            active: true,
            referenceTable: 'wf_context',
        }),
        estimated_delivery: DateTimeColumn({
            mandatory: false,
            label: 'Estimated delivery',
            read_only: false,
            active: true,
        }),
        flow_context: ReferenceColumn({
            mandatory: false,
            label: 'Flow Context',
            read_only: false,
            active: true,
            referenceTable: 'sys_flow_context',
        }),
        order_guide: ReferenceColumn({
            mandatory: false,
            label: 'Order Guide',
            read_only: false,
            active: true,
            referenceTable: 'sc_cat_item_guide',
        }),
        price: GenericColumn({
            mandatory: false,
            label: 'Price',
            read_only: false,
            active: true,
            column_type: 'currency',
        }),
        quantity: IntegerColumn({ mandatory: false, label: 'Quantity', read_only: false, active: true, default: 1 }),
        recurring_frequency: ChoiceColumn({
            choices: {},
            dropdown: 'dropdown_with_none',
            mandatory: false,
            label: 'Recurring Price Frequency',
            read_only: false,
            active: true,
        }),
        recurring_price: GenericColumn({
            mandatory: false,
            label: 'Recurring Price',
            read_only: false,
            active: true,
            default: '0',
            column_type: 'price',
        }),
        request: ReferenceColumn({
            mandatory: false,
            label: 'Request',
            read_only: false,
            active: true,
            referenceTable: 'sc_request',
        }),
        requested_for: ReferenceColumn({
            mandatory: false,
            label: 'Requested for',
            read_only: false,
            active: true,
            default: 'javascript:gs.getUserID()',
            referenceTable: 'sys_user',
        }),
        sc_catalog: ReferenceColumn({
            mandatory: false,
            label: 'Catalog',
            read_only: true,
            active: true,
            referenceTable: 'sc_catalog',
        }),
        stage: GenericColumn({
            mandatory: false,
            label: 'Stage',
            read_only: true,
            active: true,
            default: 'waiting_for_approval',
            column_type: 'workflow',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
    },
})
